TYPE VAR_INFO :
STRUCT
    udiSize : UDINT;
    udiAlignment : UDINT;
    pbyData : POINTER TO BYTE;
    udiTypeClass : UDINT;
    udiTypeSubClass : UDINT;
    udiArrayLength : UDINT;
    sName : STRING(255);
END_STRUCT
END_TYPE;

FUNCTION_BLOCK FB_FIFO
VAR_INPUT
    enqueue : BOOL;
    dequeue : BOOL;
    reset : BOOL;
END_VAR
VAR_OUTPUT
    elementCount : DINT;
    status : WORD;
END_VAR
VAR_IN_OUT
    item : VARIANT;
    buffer : VARIANT;
END_VAR
VAR
    rtEnq : R_TRIG;
    rtDeq : R_TRIG;

    init : BOOL := FALSE;
    capacity : DINT := 0;
    count : DINT := 0;
    head : UDINT := 0;
    tail : UDINT := 0;

