        END_IF;
        pBuf := infoBuf.pbyData;
        pItem := infoItem.pbyData;
        head := 0;
        tail := 0;
        count := 0;
        init := TRUE;
    ELSE
        elementCount := 0;
        status := 16#0000;
        RETURN;
    END_IF;
END_IF;

IF reset THEN
    head := 0;
    tail := 0;
    count := 0;
    elementCount := 0;
    status := 16#0000;
    RETURN;
END_IF;

IF tmpDeq THEN
    IF count > 0 THEN
        pSrc := pBuf + (head * elemSize);
        pDst := pItem;
        FOR i := UDINT#0 TO elemSize - UDINT#1 DO
            pDst[i] := pSrc[i];
        END_FOR;
        head := (head + UDINT#1) MOD TO_UDINT(capacity);
        count := count - 1;
    ELSE
        status := 16#8001;
    END_IF;
END_IF;

IF tmpEnq THEN
    IF count < capacity THEN
        pDst := pBuf + (tail * elemSize);
        pSrc := pItem;
        FOR i := UDINT#0 TO elemSize - UDINT#1 DO
            pDst[i] := pSrc[i];
        END_FOR;
        tail := (tail + UDINT#1) MOD TO_UDINT(capacity);
        count := count + 1;
    ELSE
        IF status = 16#0000 THEN
            status := 16#8002;
        END_IF;
    END_IF;
END_IF;

elementCount := count;

